// ─── Подготовка списков устройств для выбора в настройках ───────────────────
var co2List      = getServiceList([HS.CarbonDioxideSensor], HC.CarbonDioxideLevel);
var aqList       = getServiceList([HS.AirQualitySensor],    HC.AirQuality);
var vocList      = getServiceList([HS.AirQualitySensor],    HC.VOCDensity);
var pm25List     = getServiceList([HS.AirQualitySensor],    HC.PM2_5Density);
var tempList     = getServiceList([HS.TemperatureSensor],   HC.CurrentTemperature);
var secList      = getServiceList([HS.SecuritySystem],      HC.SecuritySystemCurrentState);
var contactList  = getServiceList([HS.ContactSensor],      HC.ContactSensorState);
var leakList     = getServiceList([HS.LeakSensor],          HC.LeakDetected);
var presenceList = getServiceList([HS.OccupancySensor],     HC.OccupancyDetected)
                     .concat(getServiceList([HS.MotionSensor], HC.MotionDetected).slice(1));

info = {
  name: "🪟 Окно — проветривание v1.4",
  description: "Открывает и закрывает окно (привод) по CO₂ и качеству воздуха. Гистерезис, мин. время открытия/закрытия, макс. время проветривания, запрет по уличной температуре и уличному PM2.5, режим охраны, ночная позиция, запрет открытия при присутствии в комнате, пауза автоматики при ручном управлении, защита по датчику препятствия.",
  version: "1.4",
  author: "Andrey",
  onStart: true,

  sourceServices: [HS.Window, HS.WindowCovering],
  sourceCharacteristics: [HC.TargetPosition],

  options: {

    // ── Комната ─────────────────────────────────────────────────────────────
    room: {
      name: { ru: "Комната (для логов)", en: "Room (for logs)" },
      type: "String",
      value: "Спальня"
    },

    // ── Датчики в комнате ───────────────────────────────────────────────────
    co2Sensor: {
      name: { ru: "Датчик CO₂", en: "CO₂ sensor" },
      desc: { ru: "CarbonDioxideSensor. Если не задан — CO₂ не учитывается.", en: "Empty = ignored." },
      type: "String", value: "", formType: "list", values: co2List
    },
    aqSensor: {
      name: { ru: "Качество воздуха — сервис 1", en: "Air quality service 1" },
      desc: { ru: "Индекс «Качество воздуха» 1=Отличное … 5=Плохое. Берётся худший из четырёх. «Неизвестно» (0) игнорируется. Например: TVOC, Формальдегид, AQI.", en: "Worst of three is used, 0 ignored." },
      type: "String", value: "", formType: "list", values: aqList
    },
    aqSensor2: {
      name: { ru: "Качество воздуха — сервис 2", en: "Air quality service 2" },
      type: "String", value: "", formType: "list", values: aqList
    },
    aqSensor3: {
      name: { ru: "Качество воздуха — сервис 3", en: "Air quality service 3" },
      type: "String", value: "", formType: "list", values: aqList
    },
    aqSensor4: {
      name: { ru: "Качество воздуха — сервис 4", en: "Air quality service 4" },
      type: "String", value: "", formType: "list", values: aqList
    },
    vocSensor: {
      name: { ru: "Датчик VOC (мкг/м³)", en: "VOC sensor" },
      desc: { ru: "Опционально. Если не задан — VOC не учитывается.", en: "Optional." },
      type: "String", value: "", formType: "list", values: vocList
    },

    obstacleSensor: {
      name: { ru: "Датчик препятствия окна", en: "Window obstacle sensor" },
      desc: { ru: "ContactSensor: 1 = препятствие. Если не задан — ищется ContactSensor в том же устройстве, что и привод.", en: "Empty = auto-detect in the same accessory." },
      type: "String", value: "", formType: "list", values: contactList
    },
    positionTolerance: { name: { ru: "Допуск позиции (%)", en: "Position tolerance %" }, desc: { ru: "Отклонение от заданной сценарием позиции, которое не считается ручным управлением.", en: "" }, type: "Integer", value: 3 },

    // ── Пороги ──────────────────────────────────────────────────────────────
    // CO₂ и VOC переводятся в тот же индекс 1–5, что и «Качество воздуха».
    // Итоговый индекс — худший из всех датчиков, по нему выбирается позиция окна.
    co2Open:  { name: { ru: "CO₂ ≥ (ppm) → индекс 3", en: "CO₂ → level 3" }, type: "Integer", value: 1000 },
    co2Level4:{ name: { ru: "CO₂ ≥ (ppm) → индекс 4", en: "CO₂ → level 4" }, type: "Integer", value: 1200 },
    co2Boost: { name: { ru: "CO₂ ≥ (ppm) → индекс 5", en: "CO₂ → level 5" }, type: "Integer", value: 1400 },
    co2Close: { name: { ru: "CO₂: закрыть при ≤ (ppm)", en: "CO₂ close ≤" }, type: "Integer", value: 700 },

    vocOpen:  { name: { ru: "VOC ≥ → индекс 3", en: "VOC → level 3" }, type: "Integer", value: 1000 },
    vocLevel4:{ name: { ru: "VOC ≥ → индекс 4", en: "VOC → level 4" }, type: "Integer", value: 1500 },
    vocBoost: { name: { ru: "VOC ≥ → индекс 5", en: "VOC → level 5" }, type: "Integer", value: 2000 },
    vocClose: { name: { ru: "VOC: закрыть при ≤", en: "VOC close ≤" }, type: "Integer", value: 500 },

    aqClose: { name: { ru: "Индекс качества: закрыть при ≤ (1-5)", en: "AQ close ≤" }, desc: { ru: "1 = Отличное, 2 = Хорошее", en: "" }, type: "Integer", value: 2 },

    // ── Положение окна по итоговому индексу ────────────────────────────────
    pos2: { name: { ru: "Позиция при индексе 2 — Хорошее (%)",   en: "Position at level 2 %" }, desc: { ru: "0 — при этом индексе не открывать.", en: "0 = don't open" }, type: "Integer", value: 0 },
    pos3: { name: { ru: "Позиция при индексе 3 — Среднее (%)",   en: "Position at level 3 %" }, type: "Integer", value: 30 },
    pos4: { name: { ru: "Позиция при индексе 4 — Низкое (%)",    en: "Position at level 4 %" }, type: "Integer", value: 60 },
    pos5: { name: { ru: "Позиция при индексе 5 — Плохое (%)",    en: "Position at level 5 %" }, type: "Integer", value: 100 },
    levelDownMin: { name: { ru: "Задержка уменьшения позиции (мин)", en: "Step-down delay, min" }, desc: { ru: "Увеличение позиции — сразу, уменьшение — не чаще чем раз в N мин, чтобы окно не дёргалось на границе индексов.", en: "" }, type: "Integer", value: 5 },
    nightPosition: { name: { ru: "Максимальная позиция ночью (%)",  en: "Night max position %" }, desc: { ru: "Ограничение открытия ночью (шум/холод). 0 — ночью не открывать.", en: "" }, type: "Integer", value: 20 },

    // ── Тайминги ────────────────────────────────────────────────────────────
    minOpenMin:   { name: { ru: "Мин. время открытия (мин)",  en: "Min open, min"   }, desc: { ru: "Не закрывать раньше, даже если воздух уже чистый.", en: "" }, type: "Integer", value: 10 },
    minClosedMin: { name: { ru: "Мин. пауза после закрытия (мин)", en: "Min closed, min" }, type: "Integer", value: 10 },
    maxOpenMin:   { name: { ru: "Макс. время проветривания (мин)", en: "Max open, min" }, desc: { ru: "Закрыть принудительно по истечении. 0 — без ограничения.", en: "0 = unlimited" }, type: "Integer", value: 60 },
    limitCooldownMin: { name: { ru: "Пауза после лимита проветривания (мин)", en: "Cooldown after max open" }, desc: { ru: "Если закрыли по макс. времени, а воздух так и не стал чистым — следующее открытие не раньше чем через это время. Защита от бесконечного цикла при «залипшем» датчике.", en: "" }, type: "Integer", value: 120 },
    manualPauseMin: { name: { ru: "Пауза при ручном управлении (мин)", en: "Manual pause, min" }, desc: { ru: "Если окно двигали вручную или другим сценарием — автоматика не вмешивается это время.", en: "" }, type: "Integer", value: 60 },

    // ── Ограничения ─────────────────────────────────────────────────────────
    outdoorTemp: {
      name: { ru: "Уличный датчик температуры", en: "Outdoor temperature sensor" },
      desc: { ru: "Если не задан — не учитывается.", en: "Empty = ignored." },
      type: "String", value: "", formType: "list", values: tempList
    },
    minOutdoorTemp: { name: { ru: "Не открывать, если на улице ниже (°C)", en: "Min outdoor temp" }, type: "Integer", value: 5 },
    maxOutdoorTemp: { name: { ru: "Не открывать, если на улице выше (°C)", en: "Max outdoor temp" }, desc: { ru: "Жара — пусть работает кондиционер.", en: "" }, type: "Integer", value: 30 },

    outdoorPm25: {
      name: { ru: "Уличный датчик PM2.5", en: "Outdoor PM2.5 sensor" },
      desc: { ru: "Если на улице грязнее порога — не открывать. Не задан — не учитывается.", en: "" },
      type: "String", value: "", formType: "list", values: pm25List
    },
    maxOutdoorPm25: { name: { ru: "Не открывать при уличном PM2.5 ≥ (мкг/м³)", en: "Max outdoor PM2.5" }, type: "Integer", value: 35 },

    securityService: {
      name: { ru: "Режим дома (сигнализация / хаб)", en: "Security system" },
      desc: { ru: "0=Дома, 1=Не дома, 2=Ночь. «Не дома» — окно закрывается. Не задан — считаем «Дома».", en: "" },
      type: "String", value: "", formType: "list", values: secList
    },
    nightStart: { name: { ru: "Начало ночи (ЧЧ:ММ)", en: "Night start" }, type: "String", value: "23:00" },
    nightEnd:   { name: { ru: "Конец ночи (ЧЧ:ММ)",  en: "Night end"   }, type: "String", value: "07:00" },

    rainSensor: {
      name: { ru: "Датчик дождя (протечка)", en: "Rain sensor (leak)" },
      desc: { ru: "LeakSensor, «Да» = дождь: окно закрывается и не открывается. Например, «Дождь» метеостанции WS90.", en: "" },
      type: "String", value: "", formType: "list", values: leakList
    },
    // ── Присутствие в комнате ───────────────────────────────────────────────
    presenceSensor: {
      name: { ru: "Датчик присутствия в комнате", en: "Room presence sensor" },
      desc: { ru: "OccupancySensor или MotionSensor. Пока в комнате кто-то есть — окно не открывается. Не задан — не учитывается.", en: "" },
      type: "String", value: "", formType: "list", values: presenceList
    },
    presenceMode: {
      name: { ru: "Если окно уже открыто и кто-то вошёл", en: "If window is open on entry" },
      type: "String", value: "keep", formType: "list",
      values: [
        { name: { ru: "Оставить как есть (не открывать сильнее)", en: "Keep, don't open more" }, value: "keep" },
        { name: { ru: "Закрыть окно", en: "Close window" }, value: "close" }
      ]
    },
    presenceHoldMin: { name: { ru: "Не открывать после ухода из комнаты (мин)", en: "Hold after presence, min" }, desc: { ru: "Защита от «моргания» датчика: открытие только если в комнате никого нет N мин.", en: "" }, type: "Integer", value: 5 },
    presenceNight: {
      name: { ru: "Учитывать присутствие ночью", en: "Use presence at night" },
      desc: { ru: "ВЫКЛ — ночью окно проветривает и при присутствии (спящий ребёнок, CO₂ к утру растёт), с учётом ночной позиции.", en: "" },
      type: "Boolean", value: true
    },

    rainHoldMin: { name: { ru: "Не открывать после дождя (мин)", en: "Hold after rain, min" }, desc: { ru: "Запрет держится N мин после окончания дождя (датчик дождя часто «моргает»).", en: "" }, type: "Integer", value: 30 },

    // ── Уведомления и лог ───────────────────────────────────────────────────
    tgNotify: {
      name: { ru: "Telegram: уведомлять об открытии/закрытии", en: "Telegram notify" },
      desc: { ru: "Основной путь — глобальная функция sendTG. Если её нет, отправка через Notify в канал ниже.", en: "" },
      type: "Boolean", value: false
    },
    tgChannel: {
      name: { ru: "Telegram: канал уведомлений (запасной)", en: "Notify channel (fallback)" },
      type: "String", value: "telegram_1"
    },
    tgTest: {
      name: { ru: "Telegram: тест при сохранении", en: "Telegram test on save" },
      desc: { ru: "Отправить тестовое сообщение при старте сценария. Выключите после проверки.", en: "" },
      type: "Boolean", value: false
    },
    logEnabled: {
      name: { ru: "Логирование событий", en: "Event logging" },
      desc: { ru: "Открытия/закрытия и смена причин. Ошибки пишутся всегда.", en: "" },
      type: "Boolean", value: false
    }
  },

  variables: {
    windowSvc: undefined,
    cron: undefined,
    started: false,
    autoOpen: false,
    openedTs: 0,
    closedTs: 0,
    lastSetPos: undefined,
    lastSetTs: 0,
    manualUntil: 0,
    lastReason: undefined,
    obstacleSvc: undefined,
    obstacleActive: false,
    limitUntil: 0,
    rainUntil: 0,
    presenceUntil: 0
  }
};

var TAG = "[Окно]";

// ═══════════════════════════════════════════════════════════════════════════
// ТОЧКА ВХОДА — изменение TargetPosition окна и onStart
// ═══════════════════════════════════════════════════════════════════════════
function trigger(source, value, variables, options, context) {
  try {
    variables.windowSvc = source.getService();
    if (!variables.obstacleSvc) variables.obstacleSvc = findObstacle(variables.windowSvc, options);
    var v = (typeof value === "object" && value !== null) ? value.value : value;
    var pos = parseInt(v, 10);

    if (!variables.started) {
      // Первый вызов после старта: состояние восстанавливаем по факту
      variables.started = true;
      variables.autoOpen = (pos > 0);
      variables.openedTs = pos > 0 ? Date.now() : 0;
      variables.closedTs = 0;
      log(options, "Старт. Текущая позиция " + pos + "%");
      if (options.tgTest) sendTg(options, "🔔 тестовое сообщение, сценарий запущен (окно " + pos + "%)", true);
    } else if (checkObstacle(variables, options)) {
      // Привод остановился из-за препятствия — это не ручное управление, обработано в checkObstacle
    } else if (isMoving(variables.windowSvc)) {
      // Промежуточные значения во время движения не считаем ручным управлением
    } else if (!isOwnChange(pos, variables, options)) {
      var pause = toInt(options.manualPauseMin, 60);
      variables.manualUntil = Date.now() + pause * 60000;
      variables.autoOpen = false;
      if (pos === 0) variables.closedTs = Date.now();
      log(options, "Ручное управление (" + pos + "%) — автоматика на паузе " + pause + " мин");
    }

    setupCron(variables, options);
  } catch (e) {
    console.error(TAG + " trigger: " + e.message);
  }
}

// Изменение, которое сделал сам сценарий: то же значение и не позже 2 минут
function isOwnChange(pos, variables, options) {
  var tol = toInt(options.positionTolerance, 3);
  return variables.lastSetPos !== undefined &&
         Math.abs(pos - variables.lastSetPos) <= tol &&
         (Date.now() - variables.lastSetTs) < 120000;
}

function setupCron(variables, options) {
  if (variables.cron) return;
  variables.cron = Cron.schedule("30 * * * * *", function() {
    try { runLogic(variables, options); }
    catch (e) { console.error(TAG + " [" + room(options) + "] cron: " + e.message); }
  });
}

// ═══════════════════════════════════════════════════════════════════════════
// ОСНОВНАЯ ЛОГИКА
// ═══════════════════════════════════════════════════════════════════════════
function runLogic(variables, options) {
  var svc = variables.windowSvc;
  if (!svc) return;

  var now = Date.now();
  var curPos = toInt(svc.getCharacteristic(HC.TargetPosition).getValue(), 0);

  // ── 0. Препятствие и движение ───────────────────────────────────────────
  if (checkObstacle(variables, options)) return;
  if (isMoving(svc)) return;

  // ── 1. Ручная пауза ──────────────────────────────────────────────────────
  if (variables.manualUntil > now) { setReason(variables, options, "Пауза после ручного управления"); return; }
  if (variables.manualUntil) { variables.manualUntil = 0; log(options, "Пауза закончилась — автоматика снова работает"); }

  // ── 2. Принудительное закрытие ───────────────────────────────────────────
  var block = getBlockReason(options, variables);
  if (block) {
    setReason(variables, options, block);
    if (curPos > 0) setPosition(svc, 0, block, variables, options);
    return;
  }

  // ── 3. Датчики в комнате → итоговый индекс 1..5 ─────────────────────────
  var co2 = readSensor(options.co2Sensor, HC.CarbonDioxideLevel);
  var aq  = readWorstAQ([options.aqSensor, options.aqSensor2, options.aqSensor3, options.aqSensor4]);
  var voc = readSensor(options.vocSensor, HC.VOCDensity);
  if (co2 === null && aq === null && voc === null) {
    setReason(variables, options, "Нет данных ни от одного датчика — окно не трогаем");
    return;
  }

  var co2Lvl = valueLevel(co2, toInt(options.co2Open, 1000), toInt(options.co2Level4, 1200), toInt(options.co2Boost, 1400));
  var vocLvl = valueLevel(voc, toInt(options.vocOpen, 1000), toInt(options.vocLevel4, 1500), toInt(options.vocBoost, 2000));
  var level  = Math.max(aq || 0, co2Lvl, vocLvl);

  var clean = (co2 === null || co2 <= toInt(options.co2Close, 700)) &&
              (aq  === null || aq  <= toInt(options.aqClose, 2)) &&
              (voc === null || voc <= toInt(options.vocClose, 500));

  var air = "индекс " + level + ", CO₂=" + fmt(co2) + " AQ=" + fmt(aq) + " VOC=" + fmt(voc);

  // ── Присутствие в комнате ───────────────────────────────────────────────
  var present = isPresent(options, variables);

  // ── 4. Целевая позиция ──────────────────────────────────────────────────
  var levelPos = positionForLevel(level, options);
  var nightMax = isNight(options) ? clampPos(toInt(options.nightPosition, 20)) : 100;
  var target   = Math.min(levelPos, nightMax);

  var minOpen   = toInt(options.minOpenMin, 10) * 60000;
  var minClosed = toInt(options.minClosedMin, 10) * 60000;
  var maxOpen   = toInt(options.maxOpenMin, 60) * 60000;
  var downMs    = toInt(options.levelDownMin, 5) * 60000;

  if (curPos > 0 && present && options.presenceMode === "close") {
    setPosition(svc, 0, "В комнате кто-то есть (" + air + ")", variables, options);
    return;
  }

  if (curPos > 0) {
    var openFor = now - (variables.openedTs || now);
    if (maxOpen > 0 && openFor >= maxOpen) {
      setPosition(svc, 0, "Проветривали " + Math.round(openFor / 60000) + " мин — лимит (" + air + ")", variables, options);
      if (!clean) variables.limitUntil = now + toInt(options.limitCooldownMin, 120) * 60000;
      return;
    }
    if (clean && openFor >= minOpen) {
      setPosition(svc, 0, "Воздух чистый (" + air + ")", variables, options);
      return;
    }
    if (nightMax === 0) {
      setPosition(svc, 0, "Ночью открывать запрещено (" + air + ")", variables, options);
      return;
    }
    if (curPos > nightMax) {
      setPosition(svc, nightMax, "Ночное ограничение " + nightMax + "% (" + air + ")", variables, options);
      return;
    }
    if (variables.autoOpen && target > 0 && target !== curPos) {
      if (target > curPos && present) {
        setReason(variables, options, "В комнате кто-то есть — сильнее не открываю (" + air + ")");
        return;
      }
      if (target > curPos) {
        setPosition(svc, target, "Воздух хуже — открываю сильнее (" + air + ")", variables, options);
        return;
      }
      if (now - variables.lastSetTs >= downMs) {
        setPosition(svc, target, "Воздух лучше — прикрываю (" + air + ")", variables, options);
        return;
      }
    }
    // target = 0, но воздух ещё не чистый — держим текущую позицию до порогов закрытия
    setReason(variables, options, "Проветривание " + curPos + "% (" + air + ")");
  } else {
    if (levelPos === 0) { setReason(variables, options, "Закрыто, воздух в норме (" + air + ")"); return; }
    if (present) { setReason(variables, options, "Нужно проветрить, но в комнате кто-то есть (" + air + ")"); return; }
    if (target === 0)   { setReason(variables, options, "Нужно проветрить, но ночью открывать запрещено"); return; }
    if (variables.limitUntil > now) {
      setReason(variables, options, "Воздух не очистился за макс. время — пауза до следующей попытки (" + air + ")");
      return;
    }
    if (variables.closedTs && now - variables.closedTs < minClosed) {
      setReason(variables, options, "Нужно проветрить — ждём паузу после закрытия");
      return;
    }
    setPosition(svc, target, "Плохой воздух (" + air + ")", variables, options);
  }
}

// Присутствие с удержанием после ухода. Недоступный датчик = присутствия нет
function isPresent(options, variables) {
  if (!options.presenceSensor) return false;
  if (options.presenceNight === false && isNight(options)) return false;
  var now = Date.now();
  var occ = null;
  var svc = getService(options.presenceSensor);
  if (svc) {
    var ch = (svc.getType() === HS.MotionSensor) ? HC.MotionDetected : HC.OccupancyDetected;
    var v = readSensor(options.presenceSensor, ch);
    if (v !== null) occ = (v === 1 || v === true);
  }
  if (occ === true) {
    variables.presenceUntil = now + toInt(options.presenceHoldMin, 5) * 60000;
    return true;
  }
  return variables.presenceUntil > now;
}

// Значение датчика → индекс 1..5 по трём порогам; 0 — нет данных
function valueLevel(v, t3, t4, t5) {
  if (v === null) return 0;
  if (v >= t5) return 5;
  if (v >= t4) return 4;
  if (v >= t3) return 3;
  return 1;
}

function positionForLevel(level, options) {
  if (level >= 5) return clampPos(toInt(options.pos5, 100));
  if (level === 4) return clampPos(toInt(options.pos4, 60));
  if (level === 3) return clampPos(toInt(options.pos3, 30));
  if (level === 2) return clampPos(toInt(options.pos2, 0));
  return 0;
}

// ═══════════════════════════════════════════════════════════════════════════
// ПРИЧИНЫ ПРИНУДИТЕЛЬНОГО ЗАКРЫТИЯ / ЗАПРЕТА ОТКРЫТИЯ
// ═══════════════════════════════════════════════════════════════════════════
function getBlockReason(options, variables) {
  if (options.rainSensor) {
    var now = Date.now();
    var rain = readSensor(options.rainSensor, HC.LeakDetected);
    if (rain === 1) {
      variables.rainUntil = now + toInt(options.rainHoldMin, 30) * 60000;
      return "Дождь";
    }
    if (variables.rainUntil > now) return "Недавно был дождь — ещё " + Math.ceil((variables.rainUntil - now) / 60000) + " мин";
  }
  if (options.securityService) {
    var sec = getService(options.securityService);
    if (sec) {
      try { if (sec.getCharacteristic(HC.SecuritySystemCurrentState).getValue() === 1) return "Режим «Не дома»"; } catch (e) {}
    }
  }
  var t = readSensor(options.outdoorTemp, HC.CurrentTemperature);
  if (t !== null) {
    if (t < toInt(options.minOutdoorTemp, 5))  return "На улице холодно (" + round1(t) + "°C)";
    if (t > toInt(options.maxOutdoorTemp, 30)) return "На улице жарко (" + round1(t) + "°C)";
  }
  var pm = readSensor(options.outdoorPm25, HC.PM2_5Density);
  if (pm !== null && pm >= toInt(options.maxOutdoorPm25, 35)) return "На улице грязный воздух (PM2.5=" + Math.round(pm) + ")";
  return null;
}

// ═══════════════════════════════════════════════════════════════════════════
// УПРАВЛЕНИЕ ОКНОМ
// ═══════════════════════════════════════════════════════════════════════════
function setPosition(svc, pos, reason, variables, options) {
  pos = clampPos(pos);
  var wasOpen = toInt(svc.getCharacteristic(HC.TargetPosition).getValue(), 0) > 0;
  variables.lastSetPos = pos;
  variables.lastSetTs = Date.now();
  svc.getCharacteristic(HC.TargetPosition).setValue(pos);

  if (pos > 0) {
    if (!wasOpen) variables.openedTs = Date.now();
    variables.autoOpen = true;
  } else {
    variables.autoOpen = false;
    variables.openedTs = 0;
    variables.closedTs = Date.now();
  }
  variables.lastReason = reason;

  var msg = (pos > 0 ? "Открываю на " + pos + "%" : "Закрываю") + ": " + reason;
  log(options, msg);
  sendTg(options, msg);
}

// ═══════════════════════════════════════════════════════════════════════════
// ДАТЧИК ПРЕПЯТСТВИЯ
// При срабатывании: стоп привода, сценарий не трогает окно до снятия
// препятствия + пауза manualPauseMin. Возвращает true, если окно трогать нельзя.
// ═══════════════════════════════════════════════════════════════════════════
function findObstacle(windowSvc, options) {
  if (options.obstacleSensor) return getService(options.obstacleSensor);
  try {
    var found = null;
    windowSvc.getAccessory().getServices().forEach(function(s) {
      if (!found && s.getType() === HS.ContactSensor) found = s;
    });
    return found;
  } catch (e) { return null; }
}

function checkObstacle(variables, options) {
  var svc = variables.obstacleSvc;
  if (!svc) return false;
  var state = 0;
  try { state = toInt(svc.getCharacteristic(HC.ContactSensorState).getValue(), 0); } catch (e) { return false; }

  if (state === 1) {
    if (!variables.obstacleActive) {
      variables.obstacleActive = true;
      stopDrive(variables.windowSvc);
      variables.autoOpen = false;
      var msg = "⚠️ Препятствие окна — привод остановлен, автоматика ждёт";
      variables.lastReason = msg;
      console.warn(TAG + " [" + room(options) + "] " + msg);
      sendTg(options, msg);
    }
    return true;
  }

  if (variables.obstacleActive) {
    variables.obstacleActive = false;
    var pause = toInt(options.manualPauseMin, 60);
    variables.manualUntil = Date.now() + pause * 60000;
    log(options, "Препятствие снято — автоматика на паузе " + pause + " мин");
  }
  return false;
}

// Стоп через C_TargetPositionState (0=закрыть, 1=открыть, 2=стоп; только запись)
function stopDrive(svc) {
  if (!svc) return;
  try {
    var c = svc.getCharacteristic(HC.C_TargetPositionState);
    if (c) c.setValue(2);
  } catch (e) { console.warn(TAG + " stopDrive: " + e.message); }
}

// PositionState: 0 = закрывается, 1 = открывается, 2 = остановлено
function isMoving(svc) {
  try {
    var c = svc.getCharacteristic(HC.PositionState);
    return c ? toInt(c.getValue(), 2) !== 2 : false;
  } catch (e) { return false; }
}

// ═══════════════════════════════════════════════════════════════════════════
// ВСПОМОГАТЕЛЬНЫЕ
// ═══════════════════════════════════════════════════════════════════════════
// Telegram: глобальная sendTG, если есть, иначе Notify в запасной канал (как в «Присутствии жильца»)
function sendTg(options, text, force) {
  if (!options || (!options.tgNotify && !force)) return;
  var msg = "🪟 " + room(options) + "\n" + text;
  try {
    if (typeof global !== "undefined" && global && typeof global.sendTG === "function") {
      global.sendTG(msg);
      return;
    }
    var ch = options.tgChannel ? String(options.tgChannel).replace(/^\s+|\s+$/g, "") : "";
    Notify.text(String(msg).replace(/_/g, "\\_")).to(ch || "telegram_1").send();
  } catch (e) {
    console.error(TAG + " Telegram: " + e.message);
  }
}

function setReason(variables, options, reason) {
  if (variables.lastReason === reason) return;
  variables.lastReason = reason;
  log(options, reason);
}

function log(options, msg) {
  if (options && options.logEnabled) console.info(TAG + " [" + room(options) + "] " + msg);
}

function room(options) { return (options && options.room) ? options.room : "-"; }

function isNight(options) {
  if (options.securityService) {
    var sec = getService(options.securityService);
    try { if (sec && sec.getCharacteristic(HC.SecuritySystemCurrentState).getValue() === 2) return true; } catch (e) {}
  }
  var now = new Date();
  var cur = now.getHours() * 60 + now.getMinutes();
  var s = parseTime(options.nightStart), e2 = parseTime(options.nightEnd);
  var start = s.h * 60 + s.m, end = e2.h * 60 + e2.m;
  if (start === end) return false;
  return (start > end) ? (cur >= start || cur < end) : (cur >= start && cur < end);
}

function parseTime(str) {
  var p = String(str || "").match(/^(\d{1,2}):(\d{2})$/);
  if (!p) return { h: 0, m: 0 };
  return { h: parseInt(p[1], 10), m: parseInt(p[2], 10) };
}

function toInt(v, def) {
  var n = parseInt(v, 10);
  return isNaN(n) ? def : n;
}

function clampPos(v) {
  var n = toInt(v, 0);
  return n < 0 ? 0 : n > 100 ? 100 : n;
}

function round1(v) { return Math.round(v * 10) / 10; }
function fmt(v) { return v === null ? "—" : String(Math.round(v)); }

// Чтение датчика с проверкой онлайна. null — не задан / недоступен
function readSensor(uuid, charType) {
  if (!uuid) return null;
  try {
    var svc = getService(uuid);
    if (!svc) return null;
    var acc = svc.getAccessory();
    var infoSvc = null;
    acc.getServices().forEach(function(s) { if (s.getType() === HS.AccessoryInformation) infoSvc = s; });
    if (infoSvc) {
      var online = infoSvc.getCharacteristic(HC.C_Online);
      if (online && online.getValue() !== true) return null;
    }
    var c = svc.getCharacteristic(charType);
    if (!c) return null;
    var val = c.getValue();
    return (val === null || val === undefined || isNaN(val)) ? null : Number(val);
  } catch (e) {
    console.warn(TAG + " readSensor(" + uuid + "): " + e.message);
    return null;
  }
}

// Худший индекс AirQuality (1..5) из нескольких сервисов; 0 = «Неизвестно» пропускаем
function readWorstAQ(uuids) {
  var worst = null;
  for (var i = 0; i < uuids.length; i++) {
    var v = readSensor(uuids[i], HC.AirQuality);
    if (v === null || v <= 0) continue;
    if (worst === null || v > worst) worst = v;
  }
  return worst;
}

function getService(uuid) {
  if (!uuid) return null;
  try {
    var parts = String(uuid).split(".");
    return Hub.getAccessory(parts[0]).getService(parts[1]);
  } catch (e) {
    console.warn(TAG + " getService(" + uuid + "): " + e.message);
    return null;
  }
}

function getServiceList(serviceTypes, charType) {
  var result = [{ name: { ru: "Не выбрано", en: "Not selected" }, value: "" }];
  var unsorted = [];
  Hub.getAccessories().forEach(function(acc) {
    acc.getServices().filter(function(svc) {
      return serviceTypes.indexOf(svc.getType()) >= 0;
    }).forEach(function(svc) {
      if (svc.getCharacteristic(charType)) {
        var accName  = acc.getName();
        var svcName  = svc.getName();
        var roomName = acc.getRoom() ? acc.getRoom().getName() : "";
        var label    = roomName + " → " + (accName === svcName ? accName : accName + " " + svcName) + " (" + svc.getUUID() + ")";
        unsorted.push({ name: { ru: label, en: label }, value: svc.getUUID() });
      }
    });
  });
  unsorted.sort(function(a, b) { return a.name.ru.localeCompare(b.name.ru); });
  unsorted.forEach(function(s) { result.push(s); });
  return result;
}
